(async () => {
  const { existsSync } = await import('node:fs');
  const docxPath = process.env.DOCX_PATH;
  if (!docxPath) {
    throw new Error('Missing required env var DOCX_PATH');
  }
  if (!existsSync(docxPath)) {
    throw new Error('Docx file does not exist at ' + docxPath);
  }
  globalThis.docxPath = docxPath;
})();

(async () => {
  const mammothMod = await import('mammoth');
  const mammoth = mammothMod.default || mammothMod;
  if (typeof mammoth.convertToMarkdown !== 'function') {
    throw new Error('mammoth: convertToMarkdown not available');
  }
  const result = await mammoth.convertToMarkdown({path: globalThis.docxPath});
  globalThis.markdown = result.value;
})();

(async () => {
  if (typeof globalThis.markdown !== 'string') {
    throw new Error('No markdown produced');
  }
  console.log(JSON.stringify({markdown: globalThis.markdown}));
})();
